using UnityEngine;
using System;
using System.Linq;
using System.IO;
using System.Collections.Generic;
using FalloutPort;
public static class WeaponLootValidation {
 public static string Run(){var checks=new List<string>();Action<bool,string> check=(ok,label)=>{checks.Add((ok?"PASS ":"FAIL ")+label);if(!ok)throw new Exception(label);};var g=UnityEngine.Object.FindAnyObjectByType<PortGame>();var inv=g.GetComponent<PortInventory>();var loadout=g.GetComponent<PortLoadout>();var loot=UnityEngine.Object.FindObjectsByType<PortWorldLoot>();try{g.menu.NewGame();g.player.enabled=false;check(inv.weapons.Count==0,"new game does not grant an arsenal");check(loot.SelectMany(x=>x.weaponIds).Distinct().Count()==44,"all 44 weapons have world loot placements");var locked=loot.First(x=>x.requiredStage==6);check(!inv.Take(locked,0),"sealed reserve cannot be looted before authorization");var loose=loot.First(x=>x.loose);check(inv.Take(loose,0),"visible loose weapon can be collected");check(inv.weapons.Count==1&&g.hasPistol,"pickup enters inventory and first weapon equips");check(!inv.Take(loose,0)&&inv.weapons.Count==1,"same pickup cannot be duplicated");check(!loose.visual.gameObject.activeSelf,"collected loose model disappears");g.stage=6;foreach(var container in loot)for(int i=0;i<container.weaponIds.Length;i++)if(!container.Taken(i))check(inv.Take(container,i),"collect "+container.weaponIds[i]);check(inv.weapons.Count==44,"all collected weapons remain owned");inv.Equip("pistol_10mm");g.ammo=7;g.reserve=77;inv.Equip("vault120_service_pistol");check(g.reserve==77,"same ammo type shares reserve");g.reserve=74;inv.Equip("minigun");g.ammo=137;g.reserve=481;inv.Equip("pistol_10mm");check(g.ammo==7&&g.reserve==74,"switching preserves magazine and ammo type");inv.Equip("minigun");check(g.ammo==137&&g.reserve==481,"heavy ammunition does not convert to pistol rounds");PortSave.Write(g,96);var s=PortSave.Read(96);check(s!=null,"loot save reads successfully");g.menu.NewGame();check(inv.weapons.Count==0&&loose.visual.gameObject.activeSelf,"new game restores world loot");PortSave.Apply(g,s);check(inv.weapons.Count==44&&inv.claimed.Count==44&&loadout.equipped.id=="minigun"&&g.ammo==137&&g.reserve==481,"save/load restores inventory, selected weapon and ammo");check(!loose.visual.gameObject.activeSelf&&!inv.Take(loose,0),"save/load prevents loot respawn and duplication");g.menu.NewGame();g.player.enabled=false;foreach(var item in loot){g.player.Teleport(item.transform.position+new Vector3(0,.08f,-1.8f),0);g.player.view.transform.rotation=Quaternion.LookRotation(item.transform.position+Vector3.up-g.player.view.transform.position);Physics.SyncTransforms();g.FindInteraction();check(g.current&&g.current.GetComponent<PortWorldLoot>()==item,"normal interaction reaches "+item.lootId);}g.stage=6;locked.Open();check(g.menu.page=="loot"&&g.paused,"container opens loot interface");g.menu.Back();check(!g.menu.Visible&&!g.paused&&Time.timeScale==1,"Back closes loot and resumes play");}finally{File.WriteAllLines("Assets/FalloutPort/WeaponLootValidation.txt",checks);g.player.enabled=true;g.menu.NewGame();g.menu.ShowTitle();}return checks.Count+" checks passed";}
}
